# Remove the RADM agent from a Windows machine.
#
#   irm https://panel.example.com/uninstall.ps1 | iex
#   powershell -ExecutionPolicy Bypass -File uninstall.ps1
#
# Stops and removes the autostart task, the agent, its config and state. The
# panel's key comes out of authorized_keys too — otherwise the panel would keep
# SSH access to the machine after the agent is gone.
#
# The device record in the panel is left alone: this runs on the machine itself
# and has no rights to change anything on the server. Delete it in the web UI
# (Device → Settings → Delete) to erase the metrics, tunnels and key.

[CmdletBinding()]
param(
    [switch]$KeepKey,
    [switch]$Yes
)

$ErrorActionPreference = "Stop"

$InstallDir = Join-Path $env:ProgramFiles "RADM"
$DataDir    = Join-Path $env:ProgramData "RADM"
$ConfigPath = Join-Path $DataDir "agent.conf"
$TaskName   = "RADM Agent"

function Die($message)  { Write-Host "error: $message" -ForegroundColor Red; exit 1 }
function Info($message) { Write-Host ":: $message" -ForegroundColor Cyan }
function Ok($message)   { Write-Host " + $message" -ForegroundColor Green }
function Warn($message) { Write-Host " ! $message" -ForegroundColor Yellow }

$identity = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $identity.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Die "run this from an administrator PowerShell"
}

if (-not $Yes) {
    $answer = Read-Host "Remove the RADM agent from this machine? [y/N]"
    if ($answer -notmatch '^(y|yes)$') { Info "cancelled"; exit 0 }
}

# Read the user the key was issued to out of the config, before deleting it.
$sshUser = ""
if (Test-Path $ConfigPath) {
    Get-Content $ConfigPath | ForEach-Object {
        if ($_ -match '^\s*ssh_user\s*=\s*(.*?)\s*$') { $sshUser = $Matches[1] }
    }
}

if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
    Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
    Ok "autostart task stopped and removed"
}

# The panel key is found by the comment the panel puts on it: "radm@<slug>".
if (-not $KeepKey) {
    $removed = $false
    $candidates = @(Join-Path $env:ProgramData "ssh\administrators_authorized_keys")
    $candidates += (Get-ChildItem (Join-Path $env:SystemDrive "Users") -Directory -ErrorAction SilentlyContinue |
        ForEach-Object { Join-Path $_.FullName ".ssh\authorized_keys" })

    foreach ($path in $candidates) {
        if (-not (Test-Path $path)) { continue }
        $lines = @(Get-Content $path)
        $kept = @($lines | Where-Object { $_ -notmatch ' radm@' })
        if ($kept.Count -ne $lines.Count) {
            Set-Content -Path $path -Value $kept -Encoding UTF8
            $removed = $true
            Ok "panel key removed from $path"
        }
    }

    if (-not $removed) {
        Warn "no panel key found in authorized_keys — it may have been added by hand"
    }
    if ($sshUser) { Info "the key was issued to user '$sshUser'" }
} else {
    Warn "panel key kept (-KeepKey) — the panel retains SSH access to this machine"
}

foreach ($path in @($InstallDir, $DataDir)) {
    if (Test-Path $path) {
        Remove-Item -Recurse -Force $path
        Ok "removed: $path"
    }
}

# sshd is left alone: it may have been installed and in use before RADM, and
# disabling someone else's service is not what was asked for.
Write-Host ""
Write-Host "Done. The agent has been removed." -ForegroundColor Green
Write-Host "Remember to delete the device in the panel, or it will sit in the list as ""offline""."
Write-Host "OpenSSH Server was left enabled — disable it by hand if it was installed only for the panel."

# RADM agent installer for Windows.
#
#   & ([scriptblock]::Create((irm https://panel.example.com/install.ps1))) -Token <TOKEN>
#   powershell -ExecutionPolicy Bypass -File install.ps1 -Token <TOKEN>
#
# Run it from an elevated PowerShell.
#
# Enrolls this machine with the panel, installs the agent as a scheduled task
# running under SYSTEM, and authorises the panel's SSH key so the web terminal
# and file browser work immediately.

[CmdletBinding()]
param(
    [string]$Token = "",
    [string]$Url = "__PANEL_URL__",   # substituted by the panel when it serves this file
    [string]$Allow = "loopback",
    [switch]$Insecure,
    [switch]$Force,
    [switch]$SkipSsh
)

$ErrorActionPreference = "Stop"

$InstallDir = Join-Path $env:ProgramFiles "RADM"
$DataDir    = Join-Path $env:ProgramData "RADM"
$Pyz        = Join-Path $InstallDir "radm-agent.pyz"
$ConfigPath = Join-Path $DataDir "agent.conf"
$StateDir   = Join-Path $DataDir "state"
$TaskName   = "RADM Agent"

function Die($message) { Write-Host "error: $message" -ForegroundColor Red; exit 1 }
function Info($message) { Write-Host ":: $message" -ForegroundColor Cyan }
function Ok($message)  { Write-Host " + $message" -ForegroundColor Green }
function Warn($message) { Write-Host " ! $message" -ForegroundColor Yellow }

# Some Windows APIs have no timeout of their own and no way to interrupt them:
# anything that reaches Windows Update (Get-/Add-WindowsCapability) can sit for
# tens of minutes on a machine pointed at an unreachable WSUS server, and a
# wedged service blocks Start-Service just as long. Running those in a child
# job turns "the installer hung" into a bounded wait and a warning.
function Invoke-Bounded($Seconds, $Label, [scriptblock]$Script, $ArgumentList = @()) {
    $job = Start-Job -ScriptBlock $Script -ArgumentList $ArgumentList
    if (Wait-Job $job -Timeout $Seconds) {
        $output = Receive-Job $job -ErrorAction SilentlyContinue
        Remove-Job $job -Force -ErrorAction SilentlyContinue
        return @{ Done = $true; Output = $output }
    }
    # Killing the child leaves DISM's own transaction to roll itself back; the
    # alternative is waiting forever, which is what we came here to avoid.
    Stop-Job $job -ErrorAction SilentlyContinue
    Remove-Job $job -Force -ErrorAction SilentlyContinue
    Warn "$Label is taking longer than ${Seconds}s - giving up on it"
    return @{ Done = $false; Output = $null }
}

# --- preflight --------------------------------------------------------------

$identity = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $identity.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Die "run this from an elevated PowerShell (Run as administrator)"
}

if ($Url -notmatch '^https?://') { Die "missing -Url (panel address)" }

# Validate by shape rather than against the placeholder: the panel rewrites
# every occurrence of it, so a literal comparison would compare the URL to
# itself. Same reasoning as install.sh.
$python = $null
foreach ($candidate in @("py", "python")) {
    $found = Get-Command $candidate -ErrorAction SilentlyContinue
    if ($found) {
        $version = & $found.Source -c "import sys; print('%d.%d' % sys.version_info[:2])" 2>$null
        if ($LASTEXITCODE -eq 0 -and [version]$version -ge [version]"3.9") {
            $python = $found.Source
            break
        }
    }
}
if (-not $python) { Die "python 3.9 or newer is required (https://www.python.org/downloads/)" }

# An enrollment token is only needed the first time; re-running to upgrade the
# agent reuses the registration already on disk.
$alreadyEnrolled = (Test-Path $ConfigPath) -and (-not $Force)
if (-not $Token -and -not $alreadyEnrolled) {
    Die "missing -Token (create one in the panel under Enroll)"
}

if ($Insecure) {
    # Only affects this process, and only because the operator asked for it.
    # This is the Windows PowerShell 5.1 mechanism, which is what ships with
    # Windows and what this script is normally run under; PowerShell 7 uses
    # HttpClient and would need -SkipCertificateCheck on each call instead.
    [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }
}

# --- enrollment -------------------------------------------------------------

$sshKey = ""
$sshUser = ""

if ($alreadyEnrolled) {
    Info "already enrolled - upgrading the agent, keeping the existing registration"
    Info "(pass -Force to register this machine as a new device instead)"
    $existing = @{}
    Get-Content $ConfigPath | ForEach-Object {
        if ($_ -match '^\s*([^#=]+?)\s*=\s*(.*?)\s*$') { $existing[$Matches[1]] = $Matches[2] }
    }
    $deviceToken = $existing["token"]
    $wsUrl       = $existing["url"]
    $sshUser     = $existing["ssh_user"]
    if (-not $deviceToken) { Die "$ConfigPath has no token; re-run with -Force and a fresh token" }
    Ok "reusing the existing registration"
} else {
    Info "enrolling with $Url"

    $payload = @{
        token      = $Token
        hostname   = $env:COMPUTERNAME
        arch       = $env:PROCESSOR_ARCHITECTURE
        os_release = (Get-CimInstance Win32_OperatingSystem).Caption
        model      = ((Get-CimInstance Win32_ComputerSystem).Manufacturer + " " +
                      (Get-CimInstance Win32_ComputerSystem).Model).Trim()
    } | ConvertTo-Json

    try {
        $response = Invoke-RestMethod -Method Post -Uri "$Url/api/enroll" `
            -ContentType "application/json" -Body $payload
    } catch {
        Die "enrollment failed - check the token and that the panel is reachable: $_"
    }

    $deviceToken = [REDACTED]
    $wsUrl       = $response.ws_url
    $sshUser     = $response.ssh_user
    $sshKey      = $response.ssh_public_key
    if (-not $deviceToken) { Die "panel did not return a device token" }

    # The login user comes from the enrollment token, i.e. from whoever created
    # it in the panel - not from this script.
    if (-not (Get-LocalUser -Name $sshUser -ErrorAction SilentlyContinue)) {
        Die @"
the panel expects to log in as '$sshUser', but there is no such local account.
       Create it, or change the SSH user in the panel under Device -> Settings.
"@
    }
    Ok "enrolled; the panel will log in as '$sshUser'"
}

# --- agent ------------------------------------------------------------------

Info "installing agent"
New-Item -ItemType Directory -Force -Path $InstallDir, $DataDir, $StateDir | Out-Null

try {
    Invoke-WebRequest -Uri "$Url/agent/radm-agent.pyz" -OutFile "$Pyz.tmp" -UseBasicParsing
} catch {
    Die "could not download the agent: $_"
}
Move-Item -Force "$Pyz.tmp" $Pyz
Ok "installed $Pyz"

$verify = if ($Insecure) { "false" } else { "true" }
@"
# Written by install.ps1 on $(Get-Date -Format o)
url = $wsUrl
token = [REDACTED]
state_dir = $StateDir
allow = $Allow
# Recorded for uninstall.ps1: it needs to know whose panel key to remove.
ssh_user = $sshUser
verify_tls = $verify
"@ | Set-Content -Path $ConfigPath -Encoding UTF8

# The config holds the device token, so it must not be world-readable. Break
# inheritance first, or the ACEs from ProgramData come straight back.
icacls $ConfigPath /inheritance:r /grant "*S-1-5-18:(F)" /grant "*S-1-5-32-544:(F)" | Out-Null
Ok "wrote $ConfigPath"

# --- SSH --------------------------------------------------------------------

# All of this is best-effort. SSH is what the web terminal and file browser
# ride on, but the agent does not need it to run, and none of it is worth
# losing the autostart registration below to a Windows Update call that never
# comes back. Every failure here warns and continues.
$sshReady = $false

if ($SkipSsh) {
    Info "skipping OpenSSH setup (-SkipSsh)"
} else {
    Info "configuring OpenSSH Server"

    if (Get-Service -Name sshd -ErrorAction SilentlyContinue) {
        # The fast path, and on an upgrade re-run the only one that matters:
        # the service exists, so the capability is installed and there is
        # nothing to ask Windows Update about.
        $sshReady = $true
    } else {
        Info "   checking Windows Update for the OpenSSH Server capability"
        $query = Invoke-Bounded 90 "the OpenSSH capability lookup" {
            (Get-WindowsCapability -Online -Name "OpenSSH.Server*" |
                Where-Object State -ne "Installed" |
                Select-Object -First 1).Name
        }

        if ($query.Done -and $query.Output) {
            Info "   installing $($query.Output) - this downloads from Windows Update"
            $add = Invoke-Bounded 600 "the OpenSSH Server install" {
                param($Name)
                Add-WindowsCapability -Online -Name $Name | Out-Null
            } @($query.Output)
            if ($add.Done -and (Get-Service -Name sshd -ErrorAction SilentlyContinue)) {
                $sshReady = $true
                Ok "installed OpenSSH Server"
            }
        } elseif ($query.Done) {
            # Reported as installed, yet no service: the capability is half
            # there. Nothing this script does will fix it.
            Warn "OpenSSH Server is installed but has no sshd service"
        }
    }
}

if ($sshReady) {
    $start = Invoke-Bounded 60 "starting sshd" {
        Set-Service -Name sshd -StartupType Automatic
        Start-Service -Name sshd -ErrorAction SilentlyContinue
    }
    $running = $start.Done -and
        (Get-Service sshd -ErrorAction SilentlyContinue).Status -eq "Running"

    # Without this the terminal opens cmd.exe, which is not what anyone reaching
    # for a remote shell on Windows expects. Worth setting even if the service
    # is currently down - it is read at login, not at startup.
    $powershell = (Get-Command powershell.exe).Source
    New-Item -Path "HKLM:\SOFTWARE\OpenSSH" -Force | Out-Null
    New-ItemProperty -Path "HKLM:\SOFTWARE\OpenSSH" -Name DefaultShell `
        -Value $powershell -PropertyType String -Force | Out-Null

    if ($running) {
        Ok "sshd is running; default shell is PowerShell"
    } else {
        Warn "sshd did not start - the web terminal and file browser stay dark until it does"
        Warn "  Start-Service sshd; Get-EventLog -LogName Application -Source sshd -Newest 10"
    }
} elseif (-not $SkipSsh) {
    Warn "could not set up OpenSSH Server; continuing without it"
    Warn "the agent will still work - the web terminal and file browser will not"
    Warn "install it by hand, then re-run this script:"
    Warn "  Add-WindowsCapability -Online -Name OpenSSH.Server~~~~0.0.1.0"
    Warn "(on a WSUS-managed machine that call needs a Windows Update server it can reach)"
}

# Deliberately not gated on $sshReady: the panel hands over its key exactly
# once, at enrollment, and a re-run reuses the registration without asking for
# it again. Writing it now means installing sshd by hand later is all that is
# left to do, instead of a re-enroll with -Force.
if ($sshKey) { try {
    # This is the step with no Linux analogue. For any account in the
    # Administrators group, Windows OpenSSH ignores ~/.ssh/authorized_keys
    # entirely and reads only administrators_authorized_keys - and it ignores
    # that too unless the ACL grants nothing beyond SYSTEM and Administrators.
    # Both failures are silent: sshd just refuses the key.
    $user = Get-LocalUser -Name $sshUser
    $isAdmin = (Get-LocalGroupMember -Group "Administrators" -ErrorAction SilentlyContinue |
        Where-Object { $_.SID -eq $user.SID })

    if ($isAdmin) {
        $authorized = Join-Path $env:ProgramData "ssh\administrators_authorized_keys"
    } else {
        $profilePath = (Get-CimInstance Win32_UserProfile |
            Where-Object SID -eq $user.SID.Value).LocalPath
        if (-not $profilePath) { $profilePath = Join-Path $env:SystemDrive "Users\$sshUser" }
        $authorized = Join-Path $profilePath ".ssh\authorized_keys"
        New-Item -ItemType Directory -Force -Path (Split-Path $authorized) | Out-Null
    }

    if (-not (Test-Path $authorized)) { New-Item -ItemType File -Force -Path $authorized | Out-Null }
    $keys = Get-Content $authorized -ErrorAction SilentlyContinue
    if ($keys -notcontains $sshKey) {
        Add-Content -Path $authorized -Value $sshKey
    }

    if ($isAdmin) {
        icacls $authorized /inheritance:r /grant "*S-1-5-18:(F)" /grant "*S-1-5-32-544:(F)" | Out-Null
    } else {
        icacls $authorized /inheritance:r /grant "*S-1-5-18:(F)" /grant "${sshUser}:(F)" | Out-Null
    }
    Ok "authorised the panel key for $sshUser"
} catch {
    Warn "could not authorise the panel key for ${sshUser}: $_"
} }

# --- autostart --------------------------------------------------------------

Info "registering the agent to run at startup"
$action = New-ScheduledTaskAction -Execute $python -Argument "`"$Pyz`" --config `"$ConfigPath`""
$trigger = New-ScheduledTaskTrigger -AtStartup
$principal = New-ScheduledTaskPrincipal -UserId "SYSTEM" -LogonType ServiceAccount -RunLevel Highest
# Restart-on-failure is what stands in for systemd's Restart=always; the agent
# exits non-zero on `restart_agent` and after a self-update precisely so this
# fires. ExecutionTimeLimit 0 means "never kill a long-running task".
$settings = New-ScheduledTaskSettingsSet -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) `
    -ExecutionTimeLimit ([TimeSpan]::Zero) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries

Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger `
    -Principal $principal -Settings $settings -Force | Out-Null

Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
Start-ScheduledTask -TaskName $TaskName
Start-Sleep -Seconds 3

$state = (Get-ScheduledTask -TaskName $TaskName).State
if ($state -eq "Running") {
    Ok "the agent is running"
} else {
    Write-Host "! agent did not start (state: $state); check $StateDir\agent.log" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "Done. This device should now appear in the panel." -ForegroundColor Green

"""Signed session cookies and login rate limiting."""

from __future__ import annotations

import time
from collections import defaultdict, deque

from itsdangerous import BadSignature, SignatureExpired, URLSafeTimedSerializer

from radm.config import settings

COOKIE_NAME = "radm_session"
CSRF_COOKIE = "radm_csrf"
SESSION_MAX_AGE = 14 * 86400

# Private tunnels live on their own hostnames, so the panel's host-only session
# cookie never reaches them. The panel hands out a short-lived grant instead,
# which the tunnel exchanges for a cookie of its own.
TUNNEL_COOKIE = "radm_tunnel"
TUNNEL_GRANT_MAX_AGE = 60
TUNNEL_SESSION_MAX_AGE = 12 * 3600

_serializer = URLSafeTimedSerializer(settings.session_key, salt="radm-session")
_grant_serializer = URLSafeTimedSerializer(
    settings.derived_key("tunnel-grant"), salt="radm-tunnel-grant"
)
_tunnel_serializer = URLSafeTimedSerializer(
    settings.derived_key("tunnel-session"), salt="radm-tunnel-session"
)


def issue_session(user_id: int, epoch: int) -> str:
    return _serializer.dumps({"uid": user_id, "epoch": epoch})


def read_session(raw: str | None) -> dict | None:
    """Return the session payload, or None if absent/tampered/expired."""
    if not raw:
        return None
    try:
        return _serializer.loads(raw, max_age=SESSION_MAX_AGE)
    except (BadSignature, SignatureExpired):
        return None


def issue_tunnel_grant(subdomain: str) -> str:
    """A one-minute ticket letting a signed-in operator into one tunnel."""
    return _grant_serializer.dumps({"sub": subdomain})


def read_tunnel_grant(raw: str | None, subdomain: str) -> bool:
    if not raw:
        return False
    try:
        payload = _grant_serializer.loads(raw, max_age=TUNNEL_GRANT_MAX_AGE)
    except (BadSignature, SignatureExpired):
        return False
    return payload.get("sub") == subdomain


def issue_tunnel_session(subdomain: str) -> str:
    return _tunnel_serializer.dumps({"sub": subdomain})


def read_tunnel_session(raw: str | None, subdomain: str) -> bool:
    if not raw:
        return False
    try:
        payload = _tunnel_serializer.loads(raw, max_age=TUNNEL_SESSION_MAX_AGE)
    except (BadSignature, SignatureExpired):
        return False
    # Scoped to one tunnel: a cookie for one device's camera must not open
    # another device's admin page.
    return payload.get("sub") == subdomain


class RateLimiter:
    """Sliding-window limiter keyed by client IP.

    In-process and therefore per-worker; the panel runs a single uvicorn worker
    (websocket sessions are held in memory anyway), so that is exact here.
    """

    def __init__(self, limit: int, window: int) -> None:
        self.limit = limit
        self.window = window
        self._hits: dict[str, deque[float]] = defaultdict(deque)

    def check(self, key: str) -> bool:
        """Record an attempt; return False when the caller is over the limit."""
        now = time.monotonic()
        hits = self._hits[key]
        while hits and now - hits[0] > self.window:
            hits.popleft()
        if len(hits) >= self.limit:
            return False
        hits.append(now)
        return True

    def reset(self, key: str) -> None:
        self._hits.pop(key, None)


login_limiter = RateLimiter(settings.login_rate_limit, settings.login_rate_window)
enroll_limiter = RateLimiter(30, 300)

"""Hashing, encryption and token helpers.

Device/enrollment tokens are stored as SHA-256 digests: they are already
high-entropy random strings, so a slow KDF buys nothing and would make every
agent reconnect expensive. Admin passwords are user-chosen and therefore go
through bcrypt.
"""

from __future__ import annotations

import hashlib
import hmac
import secrets

import asyncssh
import bcrypt
from cryptography.fernet import Fernet, InvalidToken

from radm.config import settings

_fernet = Fernet(settings.fernet_key)


# --- symmetric encryption for stored secrets ---------------------------


def encrypt(data: str | bytes) -> bytes:
    if isinstance(data, str):
        data = data.encode()
    return _fernet.encrypt(data)


def decrypt(blob: bytes) -> bytes:
    return _fernet.decrypt(blob)


def try_decrypt(blob: bytes) -> bytes | None:
    try:
        return _fernet.decrypt(blob)
    except InvalidToken:
        return None


# --- passwords ---------------------------------------------------------


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()


def verify_password(password: str, hashed: str) -> bool:
    try:
        return bcrypt.checkpw(password.encode(), hashed.encode())
    except ValueError:
        return False


# --- opaque tokens -----------------------------------------------------


def new_token(nbytes: int = 32) -> str:
    return secrets.token_urlsafe(nbytes)


def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode()).hexdigest()


def tokens_equal(a: str, b: str) -> bool:
    return hmac.compare_digest(a, b)


# --- ssh keys ----------------------------------------------------------


def generate_ssh_keypair(comment: str) -> tuple[str, str]:
    """Return (private_openssh, public_openssh) for a fresh ed25519 key.

    ed25519 keeps the authorized_keys line short enough to paste into an
    install script and is supported by every sshd shipped this decade.
    """
    key = asyncssh.generate_private_key("ssh-ed25519", comment=comment)
    private = key.export_private_key("openssh").decode()
    public = key.export_public_key("openssh").decode().strip()
    return private, public
